/* ---------- Espagne régionale, Portugal (1/2) ---------- */
const D38 = [
{ id:'escalivada', c:'eu', lat:41.119, lon:1.245, base:6, prep:20, cook:60, diff:1, tags:['veg','fresh','grill'],
  art:{v:'plate',bg:'#33262c',plate:'#f2e8d0',style:'salad',food:['#c9402c','#6f4a5a','#e0913a','#f0e4c0'],garnish:'#6fbf8f'},
  n:{fr:'Escalivada',en:'Escalivada'},
  p:{fr:'Tarragone, Catalogne, Espagne',en:'Tarragona, Catalonia, Spain'},
  d:{fr:"Aubergines, poivrons et oignons rôtis entiers sur la braise jusqu'à ce que la peau noircisse, puis pelés et effilochés à la main. Le verbe catalan escalivar veut dire cuire sous la cendre.",
     en:"Aubergines, peppers and onions roasted whole over embers until the skin blackens, then peeled and pulled apart by hand. The Catalan verb escalivar means to cook under ashes."},
  i:[['eggplant',3,'pc'],['red_pepper',4,'pc'],['onion',3,'pc'],['ripe_tomato',3,'pc'],['garlic',4,'clove'],['olive_oil',120,'ml'],['sherry_vinegar',2,'tbsp'],['anchovy_fillets',8,'pc'],['rustic_bread',1,'pc'],['salt',null,'']],
  s:{fr:["Posez les légumes entiers, non huilés, directement sur la braise ou sous le gril du four à 220 °C.","Tournez-les toutes les dix minutes : la peau doit noircir et cloquer partout, sans quoi elle ne se détachera pas.","Enfermez-les 20 minutes dans un plat couvert : la vapeur décolle la peau d'elle-même.","Pelez et effilochez la chair à la main, dans le sens des fibres — jamais au couteau.","Arrosez d'huile d'olive et de vinaigre de Xérès, salez, et laissez reposer deux heures. Servez tiède sur du pain grillé avec des anchois."]
     ,en:["Lay the whole vegetables, unoiled, directly on the embers or under the oven grill at 220°C.","Turn them every ten minutes: the skin must blacken and blister all over, or it will not come away.","Shut them in a covered dish for 20 minutes: the steam lifts the skin by itself.","Peel and pull the flesh apart by hand, along the fibres — never with a knife.","Dress with olive oil and sherry vinegar, salt, and rest for two hours. Serve warm on grilled bread with anchovies."]} },

{ id:'crema-catalana', c:'eu', lat:41.980, lon:2.821, base:6, prep:25, cook:15, diff:2, tags:['sweet','festive','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f0e0a8','#c9924a','#f4f0e6','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Crema catalana',en:'Crema catalana'},
  p:{fr:'Gérone, Catalogne, Espagne',en:'Girona, Catalonia, Spain'},
  d:{fr:"Une crème au lait parfumée au citron et à la cannelle, liée à la fécule et non cuite au four, brûlée au fer rouge juste avant de servir. On la mange le 19 mars, jour de la Saint-Joseph.",
     en:"A milk custard scented with lemon and cinnamon, thickened with starch rather than baked, and burnt with a hot iron just before serving. Eaten on 19 March, Saint Joseph's day."},
  i:[['whole_milk',1,'l'],['egg_yolk',8,'pc'],['sugar',250,'g'],['cornstarch',40,'g'],['lemon_zest',2,'pc'],['orange_zest',1,'pc'],['cinnamon',2,'pc'],['salt',null,'']],
  s:{fr:["Faites infuser le lait 20 minutes avec les zestes et les bâtons de cannelle, puis filtrez.","Fouettez les jaunes avec 150 g de sucre jusqu'au ruban, ajoutez la fécule sans faire de grumeau.","Versez le lait chaud en filet sur les jaunes, en fouettant, puis remettez sur feu doux.","Remuez sans arrêt en formant des huit jusqu'à épaississement, 5 minutes environ, sans jamais laisser bouillir.","Répartissez dans des plats de terre, filmez au contact et réfrigérez 4 heures. Poudrez du reste de sucre et brûlez au fer rouge à la dernière seconde."],
     en:["Infuse the milk for 20 minutes with the zests and cinnamon sticks, then strain.","Whisk the yolks with 150 g of sugar to the ribbon, then add the cornstarch without lumps.","Pour the hot milk onto the yolks in a thin stream, whisking, then return to low heat.","Stir constantly in figures of eight until it thickens, about 5 minutes, never letting it boil.","Divide between earthenware dishes, cover with film and chill for 4 hours. Dust with the remaining sugar and burn with a red-hot iron at the last second."]} },

{ id:'suquet-de-peix', c:'eu', lat:41.847, lon:3.129, base:4, prep:30, cook:40, diff:2, tags:['sea','sunday','stew'],
  art:{v:'pot',bg:'#26404c',plate:'#f2e8d0',style:'fish',food:['#e0913a','#c9402c','#f0e4c0','#8f3b2a'],garnish:'#6fbf8f'},
  n:{fr:'Suquet de peix',en:'Suquet de peix'},
  p:{fr:'Palamós, Costa Brava, Espagne',en:'Palamós, Costa Brava, Spain'},
  d:{fr:"Le ragoût de poisson des pêcheurs catalans, cuit à bord avec ce qui ne se vendait pas. Il se lie à la picada — ail, amandes, pain frit et persil pilés au mortier — versée dans les dernières minutes.",
     en:"The fish stew of Catalan fishermen, cooked on board with whatever would not sell. It is thickened with picada — garlic, almonds, fried bread and parsley pounded in a mortar — added in the final minutes."},
  i:[['monkfish',600,'g'],['red_snapper',400,'g'],['shrimp',300,'g'],['mussels',500,'g'],['potato',600,'g'],['onion',2,'pc'],['ripe_tomato',400,'g'],['garlic',6,'clove'],['almonds',50,'g'],['parsley',1,'bunch'],['white_bread',2,'slice'],['saffron',1,'pinch'],['fish_broth',700,'ml'],['olive_oil',100,'ml'],['salt',null,'']],
  s:{fr:["Faites un sofregit : oignon émincé fondu 20 minutes dans l'huile, puis tomates râpées jusqu'à réduction complète.","Ajoutez les pommes de terre en tranches épaisses cassées à la main, et le bouillon chaud safrané.","Laissez cuire 20 minutes, puis posez les poissons en gros tronçons sur les pommes de terre, sans les enfouir.","Pilez au mortier l'ail, les amandes, le pain frit et le persil en une pâte, détendez-la au bouillon et versez-la dans la casserole.","Ajoutez crevettes et moules, secouez la casserole d'un mouvement circulaire — ne remuez jamais à la cuillère — et laissez 5 minutes."],
     en:["Make a sofregit: sliced onion softened for 20 minutes in oil, then grated tomato cooked down completely.","Add the potatoes in thick pieces broken by hand, and the hot saffron broth.","Cook for 20 minutes, then lay the fish in large sections on top of the potatoes, without burying them.","Pound the garlic, almonds, fried bread and parsley into a paste, loosen it with broth and pour it into the pan.","Add the prawns and mussels, shake the pan in a circular motion — never stir with a spoon — and give it 5 minutes."]} },

{ id:'bacalao-al-pil-pil', c:'eu', lat:43.263, lon:-2.935, base:4, prep:20, cook:20, diff:3, tags:['sea','sunday','fast'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'fish',food:['#f0e0a8','#f4f0e6','#e8c46a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Bacalao al pil-pil',en:'Bacalao al pil-pil'},
  p:{fr:'Bilbao, Pays basque, Espagne',en:'Bilbao, Basque Country, Spain'},
  d:{fr:"Quatre ingrédients — morue, huile, ail, piment — et une émulsion qui tient du tour de main : la gélatine de la peau lie l'huile en une sauce jaune et brillante, obtenue au seul mouvement de la casserole.",
     en:"Four ingredients — salt cod, oil, garlic, chilli — and an emulsion that is pure sleight of hand: the gelatine from the skin binds the oil into a glossy yellow sauce, achieved by moving the pan alone."},
  i:[['salt_cod',800,'g'],['olive_oil',300,'ml'],['garlic',8,'clove'],['dried_chili',2,'pc'],['parsley',2,'tbsp']],
  s:{fr:["Dessalez la morue 48 heures à l'eau froide en changeant l'eau six fois ; gardez impérativement la peau.","Faites blondir l'ail en lamelles et le piment dans l'huile tiède, retirez-les et laissez l'huile refroidir à 60 °C.","Posez les morceaux peau vers le bas et laissez-les suer 8 minutes à feu très doux : des perles blanches de gélatine doivent apparaître.","Retirez le poisson, laissez tiédir l'huile, puis faites-la tourner dans la casserole d'un mouvement circulaire lent et continu.","L'huile blanchit et épaissit d'un coup. Remettez la morue, l'ail et le piment, secouez encore une minute et servez aussitôt."],
     en:["Desalt the cod for 48 hours in cold water, changing it six times; keep the skin at all costs.","Turn the sliced garlic and chilli golden in warm oil, lift them out and let the oil cool to 60°C.","Lay the pieces skin down and let them sweat for 8 minutes over very low heat: white beads of gelatine should appear.","Remove the fish, let the oil cool a little, then swirl it round the pan in a slow, continuous circular motion.","The oil suddenly whitens and thickens. Return the cod, garlic and chilli, shake for another minute and serve at once."]} },

{ id:'txangurro', c:'eu', lat:43.363, lon:-1.796, base:4, prep:40, cook:25, diff:2, tags:['sea','festive','bake'],
  art:{v:'plate',bg:'#26404c',plate:'#f2e8d0',style:'fish',food:['#e0703a','#f0a878','#f2e6c8','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Txangurro à la donostiarra',en:'Txangurro donostiarra'},
  p:{fr:'Hondarribia, Guipuscoa, Espagne',en:'Hondarribia, Gipuzkoa, Spain'},
  d:{fr:"De l'araignée de mer effilochée, mijotée dans un sofrito au brandy puis remise dans sa carapace et gratinée. Le txangurro est le crabe et le plat à la fois — la langue basque ne fait pas la différence.",
     en:"Spider crab picked and stewed in a brandy sofrito, then packed back into its shell and browned. Txangurro is both the crab and the dish — the Basque language makes no distinction."},
  i:[['crab',2,'kg'],['onion',2,'pc'],['leek',1,'pc'],['carrot',1,'pc'],['ripe_tomato',400,'g'],['brandy',60,'ml'],['white_wine',150,'ml'],['breadcrumbs',60,'g'],['butter',60,'g'],['olive_oil',60,'ml'],['cayenne',1,'pinch'],['parsley',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites cuire les araignées 15 minutes dans une eau très salée, puis laissez-les refroidir et décortiquez-les entièrement.","Récupérez soigneusement le corail et les parties crémeuses du coffre : c'est là qu'est tout le goût.","Faites fondre oignon, poireau et carotte hachés très fin dans l'huile, 25 minutes, puis ajoutez la tomate râpée.","Flambez au brandy, mouillez au vin blanc et laissez réduire, puis incorporez la chair, le corail et le cayenne.","Remplissez les carapaces nettoyées, parsemez de chapelure et de noisettes de beurre, et gratinez 10 minutes à 220 °C."],
     en:["Boil the crabs for 15 minutes in heavily salted water, then cool and pick them clean.","Carefully save the coral and the creamy parts from the shell: that is where all the flavour is.","Soften finely chopped onion, leek and carrot in oil for 25 minutes, then add the grated tomato.","Flame with brandy, moisten with white wine and reduce, then fold in the meat, coral and cayenne.","Fill the cleaned shells, scatter with breadcrumbs and knobs of butter, and brown for 10 minutes at 220°C."]} },

{ id:'porrusalda', c:'eu', lat:42.847, lon:-2.673, base:4, prep:20, cook:45, diff:1, tags:['veg','soup','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#7fae5a','#e0b45a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Porrusalda',en:'Porrusalda'},
  p:{fr:'Vitoria-Gasteiz, Álava, Espagne',en:'Vitoria-Gasteiz, Álava, Spain'},
  d:{fr:"Littéralement « bouillon de poireau » : poireaux, pommes de terre, carottes, et rien d'autre — sinon parfois quelques miettes de morue. La simplicité y est un principe, pas une contrainte.",
     en:"Literally 'leek broth': leeks, potatoes, carrots, and nothing else — save sometimes a few flakes of salt cod. Simplicity here is a principle, not a constraint."},
  i:[['leek',6,'pc'],['potato',700,'g'],['carrot',3,'pc'],['onion',1,'pc'],['garlic',3,'clove'],['salt_cod',200,'g'],['olive_oil',80,'ml'],['sweet_paprika',1,'tsp'],['water',1.5,'l'],['salt',null,'']],
  s:{fr:["Dessalez la morue 24 heures et effeuillez-la en petits morceaux.","Faites blondir l'ail en lamelles dans l'huile, retirez-le et réservez cette huile parfumée.","Faites suer l'oignon et le blanc des poireaux en tronçons, puis ajoutez la carotte.","Cassez les pommes de terre à la main plutôt que de les couper : les arêtes irrégulières libèrent l'amidon qui liera le bouillon.","Couvrez d'eau, cuisez 30 minutes, ajoutez la morue pour 5 minutes, puis versez l'huile à l'ail et le paprika hors du feu."],
     en:["Desalt the cod for 24 hours and flake it into small pieces.","Turn the sliced garlic golden in the oil, lift it out and keep the flavoured oil.","Sweat the onion and the white of the leeks in lengths, then add the carrot.","Break the potatoes by hand rather than cutting them: the ragged edges release the starch that will thicken the broth.","Cover with water, cook for 30 minutes, add the cod for 5 minutes, then pour in the garlic oil and paprika off the heat."]} },

{ id:'chilindron-de-cordero', c:'eu', lat:41.649, lon:-0.888, base:6, prep:30, cook:90, diff:2, tags:['lamb','slow','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9402c','#8f3b2a','#e0913a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Agneau au chilindrón',en:'Lamb chilindrón'},
  p:{fr:'Saragosse, Aragon, Espagne',en:'Zaragoza, Aragon, Spain'},
  d:{fr:"Un ragoût d'agneau aux poivrons rouges séchés, dits choriceros, dont on ne garde que la pulpe grattée à la cuillère. C'est elle qui donne à la sauce cette couleur profonde, sans une once de tomate.",
     en:"A lamb stew with dried red peppers, the choriceros, of which only the pulp scraped out with a spoon is used. That pulp gives the sauce its deep colour, without a scrap of tomato."},
  i:[['lamb_shoulder',1.5,'kg'],['dried_nyora_pepper',6,'pc'],['red_pepper',3,'pc'],['onion',3,'pc'],['garlic',6,'clove'],['serrano_ham',100,'g'],['white_wine',250,'ml'],['ripe_tomato',300,'g'],['olive_oil',100,'ml'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les poivrons séchés une heure à l'eau chaude, puis grattez la pulpe à la cuillère et jetez la peau.","Saisissez l'agneau en gros morceaux dans l'huile très chaude, par petites quantités, jusqu'à coloration franche.","Faites fondre l'oignon, l'ail et le jambon en dés dans la même cocotte, longuement.","Ajoutez les poivrons frais en lanières, la pulpe des poivrons séchés et la tomate râpée ; laissez compoter 10 minutes.","Remettez la viande, déglacez au vin blanc, ajoutez le laurier et laissez mijoter 1 h 15 à couvert."],
     en:["Soak the dried peppers in hot water for an hour, then scrape out the pulp with a spoon and discard the skin.","Sear the lamb in large pieces in very hot oil, in small batches, until well coloured.","Soften the onion, garlic and diced ham in the same pot, slowly.","Add the fresh peppers in strips, the dried pepper pulp and the grated tomato; stew for 10 minutes.","Return the meat, deglaze with white wine, add the bay and simmer covered for 1¼ hours."]} },

{ id:'ternasco-asado', c:'eu', lat:40.344, lon:-1.107, base:4, prep:20, cook:120, diff:1, tags:['lamb','sunday','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#c9754a','#8f5a2b','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Ternasco rôti',en:'Roast ternasco'},
  p:{fr:'Teruel, Aragon, Espagne',en:'Teruel, Aragon, Spain'},
  d:{fr:"L'agneau de lait aragonais, âgé de moins de trois mois, rôti simplement au saindoux, à l'ail et au vin blanc. Aucune herbe, aucune épice : la viande est trop délicate pour supporter quoi que ce soit d'autre.",
     en:"The Aragonese milk-fed lamb, under three months old, roasted simply with lard, garlic and white wine. No herbs, no spices: the meat is too delicate to carry anything else."},
  i:[['lamb_leg',1.5,'kg'],['lard',80,'g'],['garlic',8,'clove'],['white_wine',250,'ml'],['potato',1,'kg'],['coarse_salt',2,'tbsp'],['lemon',1,'pc'],['pepper',null,'']],
  s:{fr:["Frottez l'agneau de saindoux fondu, de sel et d'ail écrasé, une heure avant de l'enfourner.","Disposez les pommes de terre en rondelles épaisses au fond d'un plat de terre et posez la viande dessus.","Versez le vin blanc et un demi-verre d'eau dans le fond, jamais sur la viande.","Enfournez 1 h 45 à 170 °C en arrosant toutes les 20 minutes du jus du plat.","Montez à 220 °C dix minutes pour dorer, puis laissez reposer 15 minutes et arrosez de citron avant de découper."],
     en:["Rub the lamb with melted lard, salt and crushed garlic an hour before it goes in the oven.","Lay thick potato slices in the base of an earthenware dish and set the meat on top.","Pour the white wine and half a glass of water into the base, never over the meat.","Roast for 1¾ hours at 170°C, basting every 20 minutes with the juices.","Raise to 220°C for ten minutes to brown, then rest for 15 minutes and squeeze over lemon before carving."]} },

{ id:'menestra-de-verduras', c:'eu', lat:42.062, lon:-1.607, base:6, prep:40, cook:35, diff:2, tags:['veg','fresh','sunday'],
  art:{v:'plate',bg:'#28331f',plate:'#f2e8d0',style:'salad',food:['#7fae5a','#e8c46a','#f0e8d0','#c9754a'],garnish:'#6fbf8f'},
  n:{fr:'Menestra de légumes',en:'Menestra de verduras'},
  p:{fr:'Tudela, Navarre, Espagne',en:'Tudela, Navarre, Spain'},
  d:{fr:"Les légumes de la Ribera navarraise cuits séparément puis réunis dans un bouillon au jambon : artichauts, cardons, fèves, asperges blanches, chacun à son temps de cuisson. La rigueur est ici la recette entière.",
     en:"The vegetables of the Navarrese Ribera cooked separately then brought together in a ham broth: artichokes, cardoons, broad beans, white asparagus, each to its own timing. The discipline is the whole recipe."},
  i:[['artichoke',8,'pc'],['broad_beans',500,'g'],['white_asparagus',12,'pc'],['peas',300,'g'],['cardoon',400,'g'],['serrano_ham',150,'g'],['onion',1,'pc'],['garlic',4,'clove'],['flour',2,'tbsp'],['white_wine',150,'ml'],['olive_oil',100,'ml'],['egg',2,'pc'],['lemon',2,'pc'],['salt',null,'']],
  s:{fr:["Tournez les artichauts et plongez-les dans une eau citronnée ; effilez les cardons de la même façon.","Cuisez chaque légume séparément à l'eau salée, en le retirant al dente, et rafraîchissez-les à l'eau glacée pour fixer la couleur.","Gardez un litre d'eau de cuisson des fèves : c'est elle qui fera le bouillon.","Faites revenir l'oignon, l'ail et le jambon en dés dans l'huile, singez à la farine et mouillez au vin blanc puis à l'eau des fèves.","Réunissez tous les légumes dans cette sauce, chauffez 5 minutes sans bouillir, et décorez d'œuf dur haché."],
     en:["Turn the artichokes and drop them into lemon water; string the cardoons the same way.","Cook each vegetable separately in salted water, taking it out al dente, and refresh in iced water to fix the colour.","Keep a litre of the broad bean cooking water: that will make the broth.","Fry the onion, garlic and diced ham in oil, dust with flour and moisten with white wine then the bean water.","Bring all the vegetables together in this sauce, heat for 5 minutes without boiling, and finish with chopped hard-boiled egg."]} },

{ id:'piquillos-rellenos', c:'eu', lat:42.424, lon:-2.078, base:4, prep:40, cook:30, diff:2, tags:['sea','festive','bake'],
  art:{v:'plate',bg:'#33251c',plate:'#f2e8d0',style:'stew',food:['#c9402c','#f4f0e6','#8f3b2a','#f0e4c0'],garnish:'#7fae6a'},
  n:{fr:'Piquillos farcis à la morue',en:'Piquillo peppers stuffed with cod'},
  p:{fr:'Lodosa, Navarre, Espagne',en:'Lodosa, Navarre, Spain'},
  d:{fr:"De petits poivrons rouges rôtis au feu de bois, pelés à la main sans eau, farcis de morue en brandade et nappés d'une sauce faite des poivrons cassés. Ceux de Lodosa portent une appellation d'origine.",
     en:"Small red peppers roasted over a wood fire, peeled by hand without water, stuffed with a cod brandade and coated in a sauce made from the broken ones. Those from Lodosa carry a protected origin."},
  i:[['piquillo_pepper',16,'pc'],['salt_cod',500,'g'],['onion',2,'pc'],['garlic',5,'clove'],['heavy_cream',200,'ml'],['flour',3,'tbsp'],['olive_oil',120,'ml'],['fish_broth',300,'ml'],['whole_milk',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Dessalez la morue 36 heures, puis pochez-la 8 minutes dans le lait ; effeuillez-la et réservez le lait.","Faites fondre un oignon haché fin et deux gousses d'ail, ajoutez la morue effeuillée et la crème, et travaillez à la cuillère jusqu'à obtenir une farce liée.","Garnissez délicatement chaque piquillo à la poche à douille, sans le déchirer.","Pour la sauce, faites revenir le second oignon, ajoutez quatre piquillos cassés, singez, mouillez au bouillon et au lait, puis mixez et passez au tamis.","Rangez les piquillos dans un plat, nappez de sauce et enfournez 15 minutes à 180 °C."],
     en:["Desalt the cod for 36 hours, then poach it for 8 minutes in the milk; flake it and keep the milk.","Soften one finely chopped onion and two garlic cloves, add the flaked cod and the cream, and work with a spoon into a bound stuffing.","Fill each piquillo carefully with a piping bag, without tearing it.","For the sauce, fry the second onion, add four broken piquillos, dust with flour, moisten with broth and milk, then blend and sieve.","Arrange the peppers in a dish, coat with the sauce and bake for 15 minutes at 180°C."]} },

{ id:'patatas-a-la-riojana', c:'eu', lat:42.466, lon:-2.450, base:4, prep:15, cook:45, diff:1, tags:['comfort','pork','stew'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9402c','#e0913a','#f0e8d0','#8f3b2a'],garnish:'#7fae6a'},
  n:{fr:'Pommes de terre à la riojana',en:'Patatas a la riojana'},
  p:{fr:'Logroño, La Rioja, Espagne',en:'Logroño, La Rioja, Spain'},
  d:{fr:"Un ragoût de pommes de terre au chorizo dont Paul Bocuse disait, après l'avoir goûté en 1987, qu'il ne fallait rien y changer. Le secret tient dans le geste : on casse les pommes de terre, on ne les coupe pas.",
     en:"A potato and chorizo stew of which Paul Bocuse said, after tasting it in 1987, that nothing should be changed. The secret is in the gesture: you break the potatoes, you do not cut them."},
  i:[['potato',1,'kg'],['chorizo',300,'g'],['onion',1,'pc'],['garlic',4,'clove'],['green_pepper',1,'pc'],['dried_nyora_pepper',2,'pc'],['bay_leaf',2,'pc'],['sweet_paprika',1,'tbsp'],['olive_oil',80,'ml'],['water',1,'l'],['salt',null,'']],
  s:{fr:["Enfoncez le couteau dans la pomme de terre à mi-hauteur et cassez-la d'un coup de poignet : la cassure libère l'amidon.","Faites suer l'oignon, l'ail et le poivron dans l'huile, sans les colorer.","Ajoutez le chorizo en rondelles épaisses et laissez-le rendre sa graisse rouge deux minutes.","Incorporez les pommes de terre, remuez pour les enrober, puis ajoutez le paprika hors du feu.","Couvrez d'eau à hauteur, ajoutez laurier et poivrons séchés, et laissez frémir 35 minutes sans remuer — secouez la casserole."],
     en:["Push the knife halfway into the potato and snap it off with a twist of the wrist: the fracture releases the starch.","Sweat the onion, garlic and pepper in the oil, without colouring them.","Add the chorizo in thick rounds and let it render its red fat for two minutes.","Stir in the potatoes to coat them, then add the paprika off the heat.","Cover with water, add the bay and dried peppers, and simmer for 35 minutes without stirring — shake the pan instead."]} },

{ id:'lechazo-asado', c:'eu', lat:41.670, lon:-3.689, base:6, prep:20, cook:150, diff:2, tags:['lamb','sunday','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#c9754a','#8f5a2b','#e8d8b8','#3a2a1a'],garnish:'#7fae6a'},
  n:{fr:'Lechazo au four à bois',en:'Wood-oven lechazo'},
  p:{fr:'Aranda de Duero, Castille-et-León, Espagne',en:'Aranda de Duero, Castile and León, Spain'},
  d:{fr:"L'agneau de lait rôti dans un plat de terre au four à bois, avec pour tout assaisonnement du sel et de l'eau. La tradition castillane veut qu'on le découpe au bord de l'assiette, tant la chair se détache seule.",
     en:"Milk-fed lamb roasted in an earthenware dish in a wood oven, seasoned with nothing but salt and water. Castilian tradition has it carved with the edge of a plate, so readily does the meat fall away."},
  i:[['lamb_shoulder',2,'kg'],['coarse_salt',3,'tbsp'],['water',300,'ml'],['lard',60,'g'],['garlic',4,'clove'],['lettuce',1,'pc'],['onion',1,'pc'],['olive_oil',40,'ml'],['white_wine_vinegar',2,'tbsp']],
  s:{fr:["Choisissez un agneau de moins de trente jours, nourri exclusivement de lait : c'est toute la différence.","Posez les quartiers peau vers le bas dans un plat de terre, frottez-les de saindoux et salez généreusement.","Versez l'eau dans le fond du plat, sans jamais en mettre sur la peau.","Enfournez 1 heure à 180 °C, retournez peau vers le haut et poursuivez 1 heure en arrosant du jus.","Montez à 230 °C les 15 dernières minutes pour faire craquer la peau. Servez avec une simple salade de laitue et d'oignon."],
     en:["Choose a lamb under thirty days old, fed on milk alone: that is the whole difference.","Lay the quarters skin down in an earthenware dish, rub them with lard and salt generously.","Pour the water into the base of the dish, never onto the skin.","Roast for 1 hour at 180°C, turn skin up and continue for another hour, basting with the juices.","Raise to 230°C for the last 15 minutes to crackle the skin. Serve with a plain lettuce and onion salad."]} },

{ id:'sopa-de-ajo', c:'eu', lat:42.344, lon:-3.697, base:4, prep:15, cook:25, diff:1, tags:['soup','comfort','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#c9402c','#e0913a','#f0e8d0','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Soupe à l’ail castillane',en:'Castilian garlic soup'},
  p:{fr:'Burgos, Castille-et-León, Espagne',en:'Burgos, Castile and León, Spain'},
  d:{fr:"Du pain rassis, de l'ail, du paprika et un œuf poché dedans : la soupe des bergers de la meseta, faite avec ce qui restait. On l'appelle aussi sopa castellana, et elle se sert dans des bols de terre brûlants.",
     en:"Stale bread, garlic, paprika and an egg poached in it: the shepherd's soup of the meseta, made from what was left. Also called sopa castellana, and served in scalding earthenware bowls."},
  i:[['stale_bread',250,'g'],['garlic',10,'clove'],['serrano_ham',100,'g'],['sweet_paprika',1,'tbsp'],['smoked_paprika',1,'tsp'],['olive_oil',100,'ml'],['chicken_broth',1.2,'l'],['egg',4,'pc'],['bay_leaf',1,'pc'],['salt',null,'']],
  s:{fr:["Faites blondir doucement l'ail en lamelles dans l'huile, sans le brûler : amer, il gâcherait tout le plat.","Ajoutez le jambon en dés, puis le pain rassis en morceaux, et laissez-le s'imprégner d'huile 3 minutes.","Retirez du feu, incorporez les deux paprikas et remuez vivement — au-delà de 120 °C ils deviennent âcres.","Mouillez du bouillon chaud, ajoutez le laurier et laissez frémir 15 minutes : le pain doit se défaire.","Répartissez dans des bols de terre, cassez un œuf dans chacun et enfournez 6 minutes à 200 °C, le temps que le blanc prenne."],
     en:["Turn the sliced garlic gently golden in the oil, without burning it: bitter, it would ruin the whole dish.","Add the diced ham, then the stale bread in pieces, and let it soak up the oil for 3 minutes.","Off the heat, stir in both paprikas briskly — above 120°C they turn acrid.","Moisten with hot broth, add the bay and simmer for 15 minutes: the bread should collapse.","Divide between earthenware bowls, crack an egg into each and bake for 6 minutes at 200°C, until the white sets."]} },

{ id:'arroz-a-banda', c:'eu', lat:38.345, lon:-0.481, base:4, prep:30, cook:40, diff:2, tags:['sea','rice','sunday'],
  art:{v:'plate',bg:'#33301f',plate:'#f2e8d0',style:'rice',food:['#e0913a','#e8c46a','#f0e4c0','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Arroz a banda',en:'Arroz a banda'},
  p:{fr:'Alicante, Communauté valencienne, Espagne',en:'Alicante, Valencian Community, Spain'},
  d:{fr:"Le riz est cuit dans un fumet de poisson de roche, et le poisson servi séparément — « a banda », à part. Deux services d'un seul plat : les pêcheurs mangeaient le riz à bord et vendaient le poisson au port.",
     en:"The rice is cooked in a rockfish stock and the fish served separately — 'a banda', on the side. Two courses from one dish: fishermen ate the rice on board and sold the fish at the harbour."},
  i:[['rockfish',1,'kg'],['bomba_rice',320,'g'],['ripe_tomato',300,'g'],['garlic',6,'clove'],['dried_nyora_pepper',3,'pc'],['saffron',1,'pinch'],['sweet_paprika',1,'tsp'],['olive_oil',100,'ml'],['potato',300,'g'],['mayonnaise',200,'g'],['lemon',1,'pc'],['salt',null,'']],
  s:{fr:["Faites un fumet en cuisant les poissons de roche 25 minutes avec les pommes de terre, puis filtrez-le en pressant bien.","Faites revenir la pulpe des ñoras trempées, l'ail et la tomate râpée dans la paella, jusqu'à ce que le sofrito noircisse à peine.","Ajoutez le riz et nacrez-le 2 minutes en remuant, puis versez le fumet bouillant safrané — deux fois et demie le volume de riz.","Laissez cuire 18 minutes à feu vif puis doux, sans jamais remuer une seule fois.","Laissez reposer 5 minutes hors du feu sous un linge. Servez le riz d'abord, le poisson et l'aïoli ensuite."],
     en:["Make a stock by cooking the rockfish for 25 minutes with the potatoes, then strain it, pressing well.","Fry the soaked ñora pulp, garlic and grated tomato in the paella pan until the sofrito barely darkens.","Add the rice and toast it for 2 minutes, stirring, then pour in the boiling saffron stock — two and a half times the volume of rice.","Cook for 18 minutes over high then low heat, without stirring even once.","Rest off the heat for 5 minutes under a cloth. Serve the rice first, the fish and aioli after."]} },

{ id:'caldero-del-mar-menor', c:'eu', lat:37.626, lon:-0.996, base:6, prep:35, cook:50, diff:2, tags:['sea','rice','stew'],
  art:{v:'pot',bg:'#33251c',plate:'#f2e8d0',style:'rice',food:['#c9402c','#e0913a','#f0d8a8','#8f3b2a'],garnish:'#6fbf8f'},
  n:{fr:'Caldero du Mar Menor',en:'Caldero del Mar Menor'},
  p:{fr:'Carthagène, Murcie, Espagne',en:'Cartagena, Murcia, Spain'},
  d:{fr:"Le riz des pêcheurs de la lagune, cuit dans le chaudron de fer qui lui donne son nom, rouge de ñoras et d'un fumet de mulet. On le sert avec un aïoli si serré qu'il tient sur la cuillère à l'envers.",
     en:"The rice of the lagoon fishermen, cooked in the iron cauldron that gives it its name, red with ñoras and mullet stock. Served with an aioli so stiff it stays on an upturned spoon."},
  i:[['mullet',1.2,'kg'],['bomba_rice',400,'g'],['dried_nyora_pepper',6,'pc'],['ripe_tomato',300,'g'],['garlic',8,'clove'],['olive_oil',150,'ml'],['sweet_paprika',1,'tsp'],['egg',1,'pc'],['lemon',1,'pc'],['potato',400,'g'],['salt',null,'']],
  s:{fr:["Faites frire les ñoras entières quelques secondes dans l'huile, sans les brûler, puis pilez-les au mortier avec deux gousses d'ail.","Faites revenir la tomate râpée dans la même huile, ajoutez la pâte de ñoras et le paprika.","Mouillez de deux litres d'eau, ajoutez les poissons vidés et laissez cuire 20 minutes ; retirez-les et filtrez le bouillon.","Portez le bouillon à ébullition franche, versez le riz et laissez cuire 18 minutes sans couvrir ni remuer.","Montez l'aïoli au mortier avec l'ail restant, le jaune, le sel et l'huile en filet. Servez le riz, puis le poisson avec l'aïoli."],
     en:["Fry the whole ñoras in the oil for a few seconds, without burning them, then pound them in a mortar with two garlic cloves.","Fry the grated tomato in the same oil, add the ñora paste and the paprika.","Moisten with two litres of water, add the gutted fish and cook for 20 minutes; lift them out and strain the broth.","Bring the broth to a rolling boil, tip in the rice and cook for 18 minutes uncovered and unstirred.","Mount the aioli in a mortar with the remaining garlic, the yolk, salt and oil in a thread. Serve the rice, then the fish with the aioli."]} },

{ id:'pa-amb-oli-sobrasada', c:'eu', lat:39.570, lon:2.650, base:4, prep:15, cook:5, diff:1, tags:['pork','fast','street'],
  art:{v:'board',bg:'#33251c',plate:'#f2e6c8',style:'flat',food:['#c9402c','#e8d8b8','#8f3b2a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pa amb oli à la sobrassada',en:'Pa amb oli with sobrassada'},
  p:{fr:'Palma, Majorque, Espagne',en:'Palma, Mallorca, Spain'},
  d:{fr:"Du pain de campagne frotté de tomate de rame et d'huile, couvert de sobrassada — ce saucisson cru et tartinable au paprika, que l'humidité de l'île empêchait de sécher tout à fait. On le fait fondre au four avec du miel.",
     en:"Country bread rubbed with hanging tomato and oil, spread with sobrassada — the raw, spreadable paprika sausage that the island's damp air prevented from ever fully drying. Melted in the oven with honey."},
  i:[['rustic_bread',8,'slice'],['sobrassada',300,'g'],['ripe_tomato',4,'pc'],['olive_oil',80,'ml'],['honey',3,'tbsp'],['garlic',2,'clove'],['sheep_milk_cheese',150,'g'],['black_olives',100,'g'],['salt',null,'']],
  s:{fr:["Choisissez un pain à mie serrée, coupé en tranches d'un centimètre, et faites-le griller à peine.","Frottez-le d'une demi-gousse d'ail, puis d'une tomate de rame coupée en deux, pulpe contre la mie.","Arrosez généreusement d'huile d'olive et salez.","Étalez la sobrassada en couche épaisse, arrosez d'un filet de miel et passez 4 minutes sous le gril : elle fond et rougit.","Servez avec du fromage de brebis, des olives et un verre de vin de l'île."],
     en:["Choose a close-crumbed loaf, cut into one-centimetre slices, and toast it barely.","Rub it with half a garlic clove, then with a halved hanging tomato, pulp against the crumb.","Douse generously with olive oil and salt it.","Spread the sobrassada thickly, drizzle with honey and put it under the grill for 4 minutes: it melts and reddens.","Serve with sheep's cheese, olives and a glass of island wine."]} },

{ id:'ensaimada', c:'eu', lat:39.573, lon:2.654, base:8, prep:150, cook:25, diff:3, tags:['sweet','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f2dfa8','#e0b45a','#f4f0e6','#c98a2c'],garnish:'#c9754a'},
  n:{fr:'Ensaïmada',en:'Ensaïmada'},
  p:{fr:'Palma, Majorque, Espagne',en:'Palma, Mallorca, Spain'},
  d:{fr:"Une spirale de pâte étirée jusqu'à la transparence et badigeonnée de saindoux — saïm en majorquin, d'où son nom. Elle voyage encore dans de grandes boîtes octogonales que l'on voit dans tous les aéroports de l'île.",
     en:"A spiral of dough stretched to transparency and brushed with lard — saïm in Mallorcan, hence the name. It still travels in large octagonal boxes seen in every airport on the island."},
  i:[['flour',500,'g'],['sugar',150,'g'],['egg',3,'pc'],['warm_water',150,'ml'],['fresh_yeast',25,'g'],['lard',200,'g'],['powdered_sugar',100,'g'],['salt',null,'']],
  s:{fr:["Préparez un levain avec la levure, l'eau tiède et 100 g de farine ; laissez-le doubler une heure.","Pétrissez avec le reste de farine, le sucre, les œufs et le sel pendant 20 minutes : la pâte doit devenir très élastique.","Laissez lever 2 heures, divisez, puis étirez chaque pâton à la main sur un plan huilé jusqu'à obtenir une feuille transparente.","Badigeonnez généreusement de saindoux mou, roulez en un long boudin fin et enroulez-le en spirale lâche, en laissant de l'espace entre les tours.","Laissez pousser 12 heures à température ambiante, enfournez 20 minutes à 180 °C et poudrez abondamment de sucre glace."],
     en:["Make a starter with the yeast, warm water and 100 g of flour; let it double for an hour.","Knead with the remaining flour, sugar, eggs and salt for 20 minutes: the dough must become very elastic.","Prove for 2 hours, divide, then stretch each piece by hand on an oiled surface until translucent.","Brush generously with soft lard, roll into a long thin rope and coil it into a loose spiral, leaving space between the turns.","Prove for 12 hours at room temperature, bake for 20 minutes at 180°C and dust heavily with icing sugar."]} },

{ id:'papas-arrugadas', c:'eu', lat:28.469, lon:-16.254, base:4, prep:10, cook:30, diff:1, tags:['veg','fast','street'],
  art:{v:'bowl',bg:'#2b2a1c',plate:'#f0e4c8',style:'flat',food:['#c9a878','#8f6a4a','#c9402c','#4f8f4a'],garnish:'#6fbf8f'},
  n:{fr:'Papas arrugadas et mojos',en:'Papas arrugadas with mojo'},
  p:{fr:'Tenerife, Canaries, Espagne',en:'Tenerife, Canary Islands, Spain'},
  d:{fr:"De petites pommes de terre cuites dans une eau saturée de sel jusqu'à ce que la peau se ride et se couvre de cristaux blancs. On les trempe dans deux sauces : le mojo rouge au piment, le mojo vert à la coriandre.",
     en:"Small potatoes boiled in water saturated with salt until the skin wrinkles and frosts over with white crystals. Dipped into two sauces: red mojo with chilli, green mojo with coriander."},
  i:[['potato',1,'kg'],['coarse_salt',200,'g'],['garlic',8,'clove'],['cumin',2,'tsp'],['sweet_paprika',1,'tbsp'],['dried_chili',2,'pc'],['cilantro',1,'bunch'],['green_pepper',1,'pc'],['olive_oil',200,'ml'],['white_wine_vinegar',60,'ml'],['stale_bread',1,'slice']],
  s:{fr:["Lavez les petites pommes de terre sans les peler et mettez-les dans une casserole où elles tiennent serrées.","Couvrez d'eau à mi-hauteur et versez tout le gros sel : l'eau doit être saturée, au point qu'une pomme de terre y flotterait.","Cuisez 25 minutes à couvert, puis jetez l'eau et remettez sur feu vif deux minutes en secouant : le sel cristallise sur la peau.","Pour le mojo rouge, pilez ail, cumin, piment, paprika et pain, puis montez à l'huile et au vinaigre.","Pour le mojo vert, remplacez le piment par la coriandre et le poivron vert. Servez les deux à part."],
     en:["Wash the small potatoes without peeling and put them in a pan where they sit tightly packed.","Cover halfway with water and tip in all the coarse salt: the water should be saturated, salty enough to float a potato.","Boil covered for 25 minutes, then pour off the water and return to high heat for two minutes, shaking: the salt crystallises on the skin.","For the red mojo, pound garlic, cumin, chilli, paprika and bread, then mount with oil and vinegar.","For the green mojo, replace the chilli with coriander and green pepper. Serve both on the side."]} },

{ id:'rancho-canario', c:'eu', lat:28.124, lon:-15.430, base:6, prep:25, cook:90, diff:1, tags:['comfort','soup','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#e0913a','#c9754a','#f0e8d0','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Rancho canario',en:'Rancho canario'},
  p:{fr:'Las Palmas, Grande Canarie, Espagne',en:'Las Palmas, Gran Canaria, Spain'},
  d:{fr:"Une soupe épaisse où les pâtes courtes et les pois chiches cuisent ensemble avec le porc et le chorizo. C'est le plat des fêtes de quartier, préparé en marmites de cent litres et distribué dans la rue.",
     en:"A thick soup in which short pasta and chickpeas cook together with pork and chorizo. The dish of neighbourhood fiestas, made in hundred-litre pots and handed out in the street."},
  i:[['chickpeas',300,'g'],['macaroni',200,'g'],['pork_shoulder',400,'g'],['chorizo',200,'g'],['smoked_bacon',150,'g'],['potato',400,'g'],['onion',2,'pc'],['garlic',5,'clove'],['ripe_tomato',300,'g'],['sweet_paprika',1,'tbsp'],['saffron',1,'pinch'],['thyme',1,'tsp'],['olive_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les pois chiches une nuit avec une poignée de gros sel.","Portez-les à cuisson dans deux litres d'eau avec le porc et le lard, 1 heure à petits bouillons.","Faites revenir oignon, ail et tomate râpée à l'huile pour un sofrito, ajoutez le paprika hors du feu, puis versez le tout dans la marmite.","Ajoutez les pommes de terre en gros cubes, le chorizo en rondelles, le safran et le thym, et poursuivez 20 minutes.","Jetez les pâtes courtes pour les 10 dernières minutes. Le rancho doit rester épais : la cuillère doit y tenir presque droite."],
     en:["Soak the chickpeas overnight with a handful of coarse salt.","Cook them in two litres of water with the pork and bacon for 1 hour at a gentle boil.","Fry onion, garlic and grated tomato in oil for a sofrito, add the paprika off the heat, then tip it all into the pot.","Add the potatoes in large cubes, the sliced chorizo, saffron and thyme, and continue for 20 minutes.","Throw in the short pasta for the last 10 minutes. The rancho should stay thick: the spoon must almost stand up in it."]} },

{ id:'cocido-montanes', c:'eu', lat:43.463, lon:-3.805, base:6, prep:30, cook:150, diff:1, tags:['legume','slow','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#f0e8d0','#4f6f3a','#8f5a3a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Cocido montañés',en:'Cocido montañés'},
  p:{fr:'Santander, Cantabrie, Espagne',en:'Santander, Cantabria, Spain'},
  d:{fr:"Des haricots blancs et du chou vert mijotés avec le compango — chorizo, boudin, lard et côtes salées. Contrairement aux autres cocidos espagnols, celui-ci ne contient ni pois chiches ni bouillon servi à part.",
     en:"White beans and green cabbage stewed with the compango — chorizo, black pudding, bacon and salt ribs. Unlike other Spanish cocidos, this one has no chickpeas and no broth served separately."},
  i:[['white_beans',500,'g'],['collard_greens',700,'g'],['chorizo',250,'g'],['blood_sausage',200,'g'],['smoked_bacon',200,'g'],['smoked_pork_ribs',400,'g'],['pork_ear',1,'pc'],['onion',1,'pc'],['garlic',4,'clove'],['sweet_paprika',1,'tbsp'],['olive_oil',60,'ml'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper les haricots et dessaler les côtes et l'oreille une nuit, séparément.","Mettez les haricots à l'eau froide avec les viandes salées, portez à frémissement et écumez.","Coupez la cuisson à l'eau froide deux fois pendant la première demi-heure : c'est ce qui empêche la peau des haricots d'éclater.","Après 1 heure, ajoutez le chou vert lavé et grossièrement haché, ainsi que le chorizo et le boudin.","Faites un refrito d'ail et de paprika dans l'huile, versez-le dans la marmite et laissez encore 30 minutes. Servez tout ensemble."],
     en:["Soak the beans and desalt the ribs and ear overnight, separately.","Put the beans in cold water with the salt meats, bring to a bare simmer and skim.","Check the boil with cold water twice during the first half hour: this stops the bean skins bursting.","After 1 hour, add the washed and roughly chopped greens, along with the chorizo and black pudding.","Make a refrito of garlic and paprika in the oil, pour it into the pot and give it another 30 minutes. Serve everything together."]} },

{ id:'rabo-de-toro', c:'eu', lat:36.686, lon:-6.136, base:6, prep:30, cook:210, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f3b2a','#c9a878','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Rabo de toro',en:'Rabo de toro'},
  p:{fr:'Jerez de la Frontera, Andalousie, Espagne',en:'Jerez de la Frontera, Andalusia, Spain'},
  d:{fr:"La queue de taureau braisée au vin de Xérès pendant plus de trois heures, jusqu'à ce que la chair quitte l'os d'elle-même. On la préparait avec les bêtes tuées dans l'arène, le soir de la corrida.",
     en:"Oxtail braised in sherry for over three hours, until the meat leaves the bone of its own accord. It was made with the animals killed in the ring, on the evening of the bullfight."},
  i:[['oxtail',2,'kg'],['onion',3,'pc'],['carrot',3,'pc'],['leek',1,'pc'],['garlic',8,'clove'],['ripe_tomato',400,'g'],['red_wine',500,'ml'],['sherry_vinegar',60,'ml'],['beef_broth',700,'ml'],['flour',3,'tbsp'],['bay_leaf',3,'pc'],['cloves',3,'pc'],['olive_oil',100,'ml'],['potato',1,'kg'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Farinez les tronçons de queue et saisissez-les de tous côtés dans l'huile très chaude, par petites quantités.","Faites fondre oignon, carotte, poireau et ail dans la même cocotte, 25 minutes, jusqu'à ce qu'ils dorent.","Ajoutez la tomate râpée, laissez réduire, puis déglacez au vin rouge et au vinaigre de Xérès.","Remettez la viande, mouillez de bouillon à hauteur, ajoutez laurier et clous, et laissez mijoter 3 heures à couvert.","Retirez la viande, passez la sauce au chinois en pressant les légumes, faites-la réduire et remettez la queue dedans."],
     en:["Flour the oxtail sections and sear them on all sides in very hot oil, in small batches.","Soften onion, carrot, leek and garlic in the same pot for 25 minutes, until golden.","Add the grated tomato, reduce, then deglaze with the red wine and sherry vinegar.","Return the meat, add broth to cover, along with the bay and cloves, and simmer covered for 3 hours.","Lift out the meat, pass the sauce through a sieve pressing the vegetables, reduce it and return the oxtail to it."]} },

{ id:'arroz-de-cabidela', c:'eu', lat:41.694, lon:-8.834, base:4, prep:30, cook:50, diff:2, tags:['poultry','rice','slow'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'rice',food:['#6f2a2a','#8f3b2a','#e8dcb8','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Arroz de cabidela',en:'Arroz de cabidela'},
  p:{fr:'Viana do Castelo, Minho, Portugal',en:'Viana do Castelo, Minho, Portugal'},
  d:{fr:"Un riz de volaille lié au sang de la bête, acidulé au vinaigre pour l'empêcher de coaguler. Le plat des fermes du Minho, où rien de l'animal ne se perdait — pas même ce qui, ailleurs, se jette.",
     en:"A poultry rice bound with the bird's blood, sharpened with vinegar to stop it setting. The dish of Minho farms, where nothing of the animal was wasted — not even what elsewhere is thrown away."},
  i:[['chicken',1.5,'kg'],['pork_blood',200,'ml'],['white_vinegar',60,'ml'],['long_grain_rice',300,'g'],['onion',2,'pc'],['garlic',5,'clove'],['ripe_tomato',300,'g'],['white_wine',150,'ml'],['bay_leaf',2,'pc'],['olive_oil',80,'ml'],['parsley',4,'tbsp'],['piri_piri',1,'tsp'],['salt',null,'']],
  s:{fr:["Recueillez le sang dans un bol contenant déjà le vinaigre, et fouettez aussitôt : sans cela, il prendrait en masse.","Découpez le poulet en morceaux et faites-le revenir dans l'huile avec l'oignon, l'ail et le laurier.","Ajoutez la tomate râpée et le vin blanc, couvrez d'eau et laissez mijoter 30 minutes.","Versez le riz et laissez cuire 15 minutes, en veillant à garder le plat très humide.","Hors du feu, versez le sang vinaigré en filet en remuant sans arrêt : la sauce brunit et épaissit. Ne faites plus bouillir."],
     en:["Collect the blood in a bowl already holding the vinegar, and whisk at once: otherwise it would set solid.","Joint the chicken and fry it in the oil with the onion, garlic and bay.","Add the grated tomato and white wine, cover with water and simmer for 30 minutes.","Tip in the rice and cook for 15 minutes, keeping the dish very wet.","Off the heat, pour in the soured blood in a thin stream, stirring constantly: the sauce browns and thickens. Do not let it boil again."]} },

{ id:'sarrabulho', c:'eu', lat:41.767, lon:-8.583, base:6, prep:40, cook:120, diff:3, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#e8dcb8','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Papas de sarrabulho',en:'Papas de sarrabulho'},
  p:{fr:'Ponte de Lima, Minho, Portugal',en:'Ponte de Lima, Minho, Portugal'},
  d:{fr:"Une bouillie épaisse de pain, de viandes de porc et de sang, relevée de cumin et de citron. On la sert avec des rojões et un verre de vinho verde ; c'est le plat des marchés d'hiver du Minho.",
     en:"A thick porridge of bread, pork meats and blood, sharpened with cumin and lemon. Served with rojões and a glass of vinho verde; the dish of Minho winter markets."},
  i:[['pork_belly',500,'g'],['pork_shoulder',400,'g'],['chicken',400,'g'],['pork_blood',300,'ml'],['stale_bread',400,'g'],['onion',2,'pc'],['garlic',6,'clove'],['cumin',2,'tsp'],['lemon',2,'pc'],['white_wine',200,'ml'],['bay_leaf',2,'pc'],['lard',60,'g'],['piri_piri',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les viandes 1 h 30 dans l'eau avec l'oignon, l'ail, le laurier et le vin blanc, jusqu'à ce qu'elles se défassent.","Retirez-les, hachez-les finement au couteau et filtrez le bouillon.","Émiettez le pain rassis dans le bouillon chaud et laissez-le gonfler 15 minutes, puis écrasez-le à la cuillère de bois.","Remettez la viande, ajoutez le cumin, le piri-piri et beaucoup de poivre, et laissez épaissir 20 minutes à feu doux en remuant.","Versez le sang en filet hors du feu, en remuant sans arrêt, et finissez au jus de citron. La consistance doit être celle d'une purée coulante."],
     en:["Cook the meats for 1½ hours in water with the onion, garlic, bay and white wine, until they fall apart.","Lift them out, chop them finely by knife and strain the broth.","Crumble the stale bread into the hot broth and let it swell for 15 minutes, then crush it with a wooden spoon.","Return the meat, add the cumin, piri-piri and plenty of pepper, and thicken for 20 minutes over low heat, stirring.","Pour in the blood off the heat, stirring without pause, and finish with lemon juice. It should have the consistency of a loose purée."]} },

{ id:'caldeirada-de-peixe', c:'eu', lat:39.601, lon:-9.070, base:6, prep:30, cook:45, diff:1, tags:['sea','stew','sunday'],
  art:{v:'pot',bg:'#26404c',plate:'#f2e8d0',style:'fish',food:['#e0913a','#c9402c','#f0e4c0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Caldeirada de peixe',en:'Caldeirada de peixe'},
  p:{fr:'Nazaré, Estrémadure, Portugal',en:'Nazaré, Estremadura, Portugal'},
  d:{fr:"Le ragoût de poisson des pêcheurs de Nazaré, monté en couches dans la marmite et jamais remué : on ne fait que secouer le récipient. Plus il y a d'espèces différentes, meilleur il est.",
     en:"The fish stew of Nazaré fishermen, built in layers in the pot and never stirred: you only shake the pan. The more different species it holds, the better it is."},
  i:[['whitefish',800,'g'],['red_snapper',500,'g'],['eel',400,'g'],['potato',800,'g'],['onion',4,'pc'],['green_pepper',2,'pc'],['ripe_tomato',600,'g'],['garlic',6,'clove'],['bay_leaf',3,'pc'],['white_wine',200,'ml'],['olive_oil',150,'ml'],['parsley',1,'bunch'],['sweet_paprika',1,'tsp'],['salt',null,'']],
  s:{fr:["Taillez tous les légumes en rondelles de la même épaisseur : ils doivent cuire ensemble.","Montez la marmite en couches — oignon, pomme de terre, poivron, tomate, poisson — en salant et huilant chaque étage.","Répétez jusqu'en haut, en terminant par les légumes pour protéger le poisson.","Versez le vin blanc, l'eau à mi-hauteur seulement, le laurier et le paprika, puis couvrez.","Laissez cuire 35 minutes à feu moyen sans jamais remuer : secouez la marmite d'un mouvement circulaire toutes les dix minutes."],
     en:["Cut all the vegetables into rounds of the same thickness: they must cook together.","Build the pot in layers — onion, potato, pepper, tomato, fish — salting and oiling each storey.","Repeat to the top, finishing with vegetables to protect the fish.","Pour in the white wine, water to come only halfway, the bay and paprika, then cover.","Cook for 35 minutes over medium heat without ever stirring: shake the pot in a circular motion every ten minutes."]} },

{ id:'queijadas-de-sintra', c:'eu', lat:38.798, lon:-9.388, base:12, prep:45, cook:20, diff:2, tags:['sweet','bake','cheese'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#c98a2c','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Queijadas de Sintra',en:'Queijadas de Sintra'},
  p:{fr:'Sintra, Portugal',en:'Sintra, Portugal'},
  d:{fr:"De petites tartelettes au fromage frais, à la cannelle et à la croûte plissée à la main, attestées à Sintra depuis le XIIIe siècle — elles servaient alors à payer une partie des impôts locaux.",
     en:"Small tartlets of fresh cheese and cinnamon in a hand-pleated crust, recorded in Sintra since the 13th century — they were once used to pay part of the local taxes."},
  i:[['farmer_cheese',400,'g'],['sugar',300,'g'],['egg',4,'pc'],['flour',250,'g'],['cinnamon',2,'tsp'],['butter',40,'g'],['warm_water',100,'ml'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez 150 g de farine, l'eau tiède, le beurre fondu et le sel en une pâte souple, et laissez-la reposer 30 minutes.","Passez le fromage frais au tamis pour éliminer le moindre grumeau — la texture finale en dépend entièrement.","Mêlez-le au sucre, aux œufs, au reste de farine, à la cannelle et au zeste, jusqu'à obtenir un appareil lisse.","Étalez la pâte très finement et foncez des moules de 6 cm, en laissant dépasser un bord que vous plissez à la main.","Remplissez aux trois quarts et enfournez 20 minutes à 220 °C : le dessus doit brunir par plaques."],
     en:["Knead 150 g of flour, the warm water, melted butter and salt into a supple dough, and rest it for 30 minutes.","Push the fresh cheese through a sieve to remove every lump — the final texture depends entirely on this.","Mix it with the sugar, eggs, remaining flour, cinnamon and zest into a smooth batter.","Roll the dough very thin and line 6 cm moulds, leaving an overhanging edge that you pleat by hand.","Fill three quarters full and bake for 20 minutes at 220°C: the tops should brown in patches."]} }
];
